const PREFIX='jyothish-app-';let current;
self.addEventListener('install',e=>e.waitUntil((async()=>{const r=await fetch(new URL('offline-assets.json',self.registration.scope),{cache:'no-store'}),manifest=await r.json();current=PREFIX+manifest.version;let cache=await caches.open(current);await cache.addAll(manifest.files.map(path=>new URL(path,self.registration.scope).href));await cache.put(new URL('offline-assets.json',self.registration.scope),new Response(JSON.stringify(manifest)));await self.skipWaiting()})()));
